package br.unicamp.regras.test;

import KyberJCE.provider.Kyber1024KeyPairGenerator;
import KyberJCE.provider.Kyber512KeyPairGenerator;
import KyberJCE.provider.Kyber768KeyPairGenerator;
import KyberJCE.provider.KyberKeyAgreement;
import KyberJCE.provider.kyber.Indcpa;
import KyberJCE.provider.kyber.Poly;

import java.security.InvalidKeyException;
import java.security.KeyPair;

import org.openjdk.jmh.annotations.*;

import java.security.NoSuchAlgorithmException;
import java.util.concurrent.TimeUnit;

/**
 *  * Test to measure the simulated time used by the KyberJCE main functions
 *
 * @author Fernando Penido
 */
@BenchmarkMode(Mode.AverageTime) // average time is being measure
@OutputTimeUnit(TimeUnit.MICROSECONDS) // with microseconds as unit
@State(Scope.Thread) // the state is isolated by thread
@Warmup(iterations = 3, time = 1, timeUnit = TimeUnit.SECONDS) // warmup iterations
@Measurement(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS) // number of measurements
@Fork(1) // isolate the virtual machine
public class TimeTest_KyberJCE {
    private byte[] aliceGeneratedSecretKey;
    private byte[] bobGeneratedSecretKey;
    KeyPair bobKeyPair512;
    KeyPair bobKeyPair768;
    KeyPair bobKeyPair1024;
    Kyber512KeyPairGenerator bobKeyGen512;
    Kyber768KeyPairGenerator bobKeyGen768;
    Kyber1024KeyPairGenerator bobKeyGen1024;
    KyberKeyAgreement keyAgreement =  new KyberKeyAgreement();
    String hex512 = "19C44D35AB9EF31B1360F0BF33CF63D80E405962D698415C5888F0AF385DCFF4";
    byte[] seed512 = java.util.HexFormat.of().parseHex(hex512);
    String hexek512 = "";
    byte[] ek512 =  java.util.HexFormat.of().parseHex(hexek512);

    String hex768 = "BD8D55A47DF20F6B636E06B0ABA5F258B6E7712074B6FFFCE9153157D8B849B8";
    byte[] seed768 = java.util.HexFormat.of().parseHex(hex768);
    String hexek768 = "";
    byte[] ek768 = java.util.HexFormat.of().parseHex(hexek768);

    String hex1024 = "2C29A4DF2135AD034D6172BEF7A0A30906A82EDFD7E1E6FC5E5A00C18B90CAD7";
    byte[] seed1024 = java.util.HexFormat.of().parseHex(hex1024);
    String hexek1024 = "";
    byte[] ek1024 = java.util.HexFormat.of().parseHex(hexek1024);

    String hexct512 = "";
    byte[] ct512 = java.util.HexFormat.of().parseHex(hexct512);
    String hexdk512 = "";
    byte[] dk512 = java.util.HexFormat.of().parseHex(hexdk512);

    String hexct768 = "";
    byte[] ct768 = java.util.HexFormat.of().parseHex(hexct768);
    String hexdk768 = "";
    byte[] dk768 = java.util.HexFormat.of().parseHex(hexdk768);

    String hexct1024 = "";
    byte[] ct1024 = java.util.HexFormat.of().parseHex(hexct1024);
    String hexdk1024 = "";
    byte[] dk1024 = java.util.HexFormat.of().parseHex(hexdk1024);

    @Param({"512", "768", "1024"})
    private int securityLevel;

    /**
     * Sets the configuration of the class and initializes it
     */
    @Setup(Level.Trial)
    public void setupApplet() {

        aliceGeneratedSecretKey = new byte[32];
        bobGeneratedSecretKey = new byte[32];

        switch (securityLevel) {
            case 512:
                bobKeyGen512 = new Kyber512KeyPairGenerator();

                break;

            case 768:
                bobKeyGen768 = new Kyber768KeyPairGenerator();
                break;

            case 1024:
                bobKeyGen1024 = new Kyber1024KeyPairGenerator();
                break;

            default:
                throw new IllegalStateException("NÃ­vel de seguranÃ§a invÃ¡lido!");
        }
    }

    /**
     * Marks the time for the key generation process.
     * @return true (to avoid JMH optimizations that might skip the method)
     */
    @Benchmark
    public boolean keyGen(){
        switch(securityLevel){
            case 512:
                bobKeyPair512 = bobKeyGen512.generateKeyPair();

                break;
            case 768:
                bobKeyPair768 = bobKeyGen768.generateKeyPair();
                break;
            case 1024:
                bobKeyPair1024 = bobKeyGen1024.generateKeyPair();
                break;
            default:
                throw new IllegalStateException("Nível de segurança inválido!");
        }
        return true;
    }

    /**
     * Marks the time for the encapsulation process.
     * @return true (to avoid JMH optimizations that might skip the method)
     */
    @Benchmark
    public boolean encaps() throws NoSuchAlgorithmException, InvalidKeyException {
        switch (securityLevel) {
            case 512:
                keyAgreement.encrypt512(seed512, ek512);
                break;
            case 768:
                keyAgreement.encrypt768(seed768, ek768);
                break;
            case 1024:
                keyAgreement.encrypt1024(seed1024, ek1024);
                break;
            default:
                throw new IllegalStateException("Nível de segurança inválido!");
        }
        return true;
    }

    /**
     * Marks the time for the decapsulation process.
     * @return true (to avoid JMH optimizations that might skip the method)
     */
    @Benchmark
    public boolean decaps() throws NoSuchAlgorithmException {
        switch (securityLevel) {
            case 512:
                keyAgreement.decrypt512(ct512, dk512);
                break;
            case 768:
                keyAgreement.decrypt768(ct768, dk768);
                break;
            case 1024:
                keyAgreement.decrypt1024(ct1024, dk1024);
                break;
            default:
                throw new IllegalStateException("Nível de segurança inválido!");
        }
        return true;
    }

    @Benchmark
    public boolean generatePoly(){
        Poly.getNoisePoly(seed512, (byte) 2, 3);
        return true;
    }

    @Benchmark
    public boolean generateMatrix(){
        Indcpa.generateMatrix(seed512, false, 3);
        return true;
    }

    public static void main(String[] args) throws Exception {
        org.openjdk.jmh.runner.options.Options opt = new org.openjdk.jmh.runner.options.OptionsBuilder()
                // Pega todos os @Benchmark dentro de MLKEMBenchmark
                .include(TimeTest_KyberJCE.class.getSimpleName() + ".keyGen")
                .include(TimeTest_KyberJCE.class.getSimpleName() + ".encaps")
                .include(TimeTest_KyberJCE.class.getSimpleName() + ".decaps")
                .build();
        new org.openjdk.jmh.runner.Runner(opt).run();
    }
}

